package openapi

import (
	"maps"
	"slices"
	"sort"
	"strings"

	"github.com/hanzoai/cloud/sdk/spec"
)

// Composing: the fleet document is the COMPOSITION of its apps' documents, not a
// concatenation of them.
//
// Each app describes itself — `<app> openapi` mounts that one subsystem and
// projects its own router, so a subset is generated by exactly the machinery the
// whole document is (Spec → From/Typed/Fold). Compose puts those subsets back
// together, and the only thing it adds is the REFUSAL: two apps may not claim
// one address, and two apps may not mean different things by one schema name.
//
// That refusal is the entire point, and it is not hypothetical. The routing
// order in apps.Wire() is load-bearing precisely because overlapping claims
// exist: clients/git's /:org/:repo catch-all was swallowing other apps' routes,
// and the manifest's call-graph walk is what caught it. A merge that took
// last-write-wins would have produced a perfectly valid document describing a
// fleet nobody deploys — every generated SDK wrong, in a way no test could see.
// A document that cannot be composed is a fleet that cannot be routed; say so.
//
// What Compose does NOT do is arbitrate. It has no policy for who should win,
// because there is no such policy: an overlap is a bug at the composition root,
// and the fix is in Wire(), not here.
//
// The one exception is not a policy either, it is the matcher: an operation that
// arrived through a RELAY (openapi/relay.go — a wildcard standing for a whole
// registry) loses to one that did not, because a wildcard is registered after the
// specific paths that carve out of it and fiber picks the specific one. Compose can
// see that because a relayed operation names its own registry in x-app and a
// direct one does not, so the rule is read off the data rather than configured.
// Two specific claims, or two relays, are still a refusal.

// Part is one app's contribution: its document, the name a conflict is reported
// against, and the stage that name is at. The name is the app's, not the file's —
// a message naming two paths a human then has to map back to apps is a worse
// message.
//
// Stage is the app's manifest row (manifest.App.Stage, HIP-0139 §8), carried here
// rather than looked up because this package cannot import manifest — manifest's
// own tests read this one, so the edge would close a cycle. It arrives from
// whoever built the part, which is the same place the bytes arrive from: see
// [Subsets]. Empty is ga, exactly as the row's zero value is.
type Part struct {
	App   string
	Stage string
	Doc   *spec.Document
}

// prose is what each PRODUCT's owner says about it, keyed by product: the
// synopsis of the package that app's binary mounts, which describe.go stamped
// into that app's own subset as info.description (openapi/synopsis.go computes
// it, once, there).
//
// Reading it back off the parts is why Compose stays a pure function of its inputs.
// The alternative — looking the package up again here — would be the same mapping
// written twice, in two processes, free to disagree; the subset already carries
// the answer because the app that wrote it is the app that knows.
//
// A part whose description is the FLEET's own has said nothing about itself: that
// is FleetSpec's identity, the fallback for a package with no doc comment, and it
// describes the whole API rather than this product. Stamping it on a tag would
// give every undescribed product the same sentence, which reads as a description
// and is not one.
//
// # The tag is the app, so the tag's sentence is the app's own
//
// Every operation is tagged with the app that serves it (HIP-0139 §4), so a
// tag's description is what that app says about itself and nothing else. An app
// with no package doc (metrics, authz, licensing — each mounting a subsystem that
// lives in another module, so there is no package here to read) leaves its tag
// blank. The cure is a doc comment in that service; synthesizing a line from the
// name here would make an undescribed capability indistinguishable from a
// described one.
func prose(parts []Part) map[string]string {
	said := make(map[string]string, len(parts))
	for _, p := range parts {
		if d := p.Doc.Info.Description; d != "" && d != fleetInfo.Description {
			said[p.App] = d
		}
	}
	return said
}

// Compose composes the parts into the fleet document, or refuses.
//
// Identity (openapi version, info, servers) comes from THIS package, not from
// the parts: a subset is a partial view of one API, so the composed document is
// that same API — not a fifth one assembled out of whatever titles the parts
// happened to carry.
func Compose(parts []Part) (*spec.Document, error) {
	out := &spec.Document{
		OpenAPI: "3.1.0",
		Info:    fleetInfo,
		Servers: []spec.Server{fleetServer},
		Paths:   map[string]spec.PathItem{},
	}
	opOwner := map[string]string{} // "METHOD path" → app
	behind := map[string]bool{}    // "METHOD path" → the claim came through a relay
	schemas := spec.NewNouns()
	tags := map[string]bool{}

	for _, p := range parts {
		for _, path := range slices.Sorted(maps.Keys(p.Doc.Paths)) {
			item := p.Doc.Paths[path]
			for _, method := range slices.Sorted(maps.Keys(item)) {
				at := strings.ToUpper(method) + " " + path
				op := item[method]
				// x-app names the registry that registered the operation, and it is
				// set where that is known: [Project] stamps the module behind a relay,
				// this stamps the app for everything else. Never overwritten — an
				// operation that already named its registry knows better than the
				// part it arrived in, which is exactly the traceability the field is
				// for. Two nested relays would each stamp their own source, and the
				// innermost — the one that ran first — is the one that answers.
				relayed := op.App != "" && op.App != p.App
				if op.App == "" {
					op.App = p.App
				}
				// The tag is the owner (HIP-0139 §4): one axis, read off the value
				// every projection already carries. The path's first segment stays
				// the ADDRESS axis — public.go and misfiled.go read it — and the
				// misfiled ratchet drives the two into agreement. Compat survives
				// beside it: a fact the router cannot know and the public rule reads.
				legacy := slices.Contains(op.Tags, spec.Compat)
				op.Tags = []string{op.App}
				if legacy {
					op.Tags = append(op.Tags, spec.Compat)
				}
				// The stage is the SERVING app's, so it comes from the part and not
				// from op.App: a relayed operation names the registry behind the relay
				// in x-app, and who is shown a capability is a fact about the app whose
				// prefix the request reaches. Written unconditionally, because an app
				// describing itself cannot know it and therefore never sets it.
				op.Stage = p.Stage
				// The operator's mark is the fleet's too (openapi/operator.go), and it
				// is stamped here for the stage's reason: the app never sets it.
				op.Operator = operated[at]
				if prev, dup := opOwner[at]; dup {
					// A RELAY YIELDS TO A SPECIFIC ROUTE, because that is what the
					// matcher does: a wildcard is registered after the paths that
					// carve out of it, and fiber picks the specific one. So a claim
					// that arrived through a relay is not a rival to one that did not
					// — it is the loser, and publishing it would name a handler no
					// request reaches. apps/o11y mounts /v1/o11y/scope in front of
					// the o11y relay for exactly this reason.
					//
					// This is the ONE case Compose resolves, and it resolves it by
					// reading the router's own rule rather than by preferring an app.
					// Two specific claims, or two relays, remain a refusal: those are
					// bugs at the composition root and there is no rule that picks.
					switch {
					case relayed && !behind[at]:
						continue
					case !relayed && behind[at]:
					default:
						return nil, &spec.Conflict{Kind: "operation", Name: at, A: prev, B: p.App}
					}
				}
				opOwner[at] = p.App
				behind[at] = relayed
				if out.Paths[path] == nil {
					out.Paths[path] = spec.PathItem{}
				}
				out.Paths[path][method] = op
			}
		}

		if p.Doc.Components == nil {
			continue
		}
		if err := schemas.Add(p.App, p.Doc.Components.Schemas); err != nil {
			return nil, err
		}
	}

	// Tags are read off the COMPOSED operations, never unioned from the parts'
	// own tag lists. A part's list describes the part; if a caller contributes
	// only some of a part's paths, the union would declare a product no operation
	// in this document belongs to — which is how the composed document grew a
	// `sentry` tag with no sentry route. The document's tag list is a function of
	// the document's operations, exactly as From computes it.
	for _, item := range out.Paths {
		for _, op := range item {
			for _, t := range spec.Products(op.Tags) {
				tags[t] = true
			}
		}
	}
	said := prose(parts)
	for name := range tags {
		out.Tags = append(out.Tags, spec.Tag{Name: name, Description: said[name]})
	}
	sort.Slice(out.Tags, func(i, j int) bool { return out.Tags[i].Name < out.Tags[j].Name })

	schemas.Into(out)

	// The composed document owes the same invariant a generated one does: an
	// injective (method, path) → operation map. The path check above already
	// enforces it ACROSS apps; this catches an id collision between two
	// different addresses (the hyphen-vs-separator family operationID guards),
	// which composition can introduce even when no app is at fault.
	if err := spec.UniqueOperationIDs(out); err != nil {
		return nil, err
	}
	// The audience, asked again now that the stage is known. Each part was stamped
	// by its own [Spec] against everything an app can see about itself, and the
	// stage is the one term of the rule an app cannot see — so the rule is asked
	// once more here, over the composition, rather than a second rule being written
	// that ANDs a stage onto a mark somebody else made. See [stamp].
	spec.Stamp(out)
	// The credential is IDENTITY, like the info and server blocks above: one API,
	// one scheme, stated by this package rather than inherited from whichever part
	// happened to carry it (openapi/security.go).
	spec.Secure(out)
	return out, nil
}
